#include <stdio.h>

/* 把外面那张牌往后挪一只碗；挪过了最后一只就绕回第一只 */
void step(int **pp, int *base, int count) {
    *pp = *pp + 1;
    if (*pp == base + count) {
        *pp = base;
    }
}

int main(void) {
    int bowls[4] = {{row}};
    int *p = &bowls[0];

    for (int i = 0; i < 6; i++) {
        printf("%d\n", *p);
        step(&p, &bowls[0], 4);
    }
    return 0;
}
